/// <summary>
/// Called from markupTableDS.active() and METMarkupTableFrm_MarkupTableIsOffRemittance_Extension.modified
/// </summary>
/// <param name = "_markupTableDS">MarkupTable form data source</param>
static void allowEdit(FormDataSource _markupTableDS)
{
    MarkupTable markupTable = _markupTableDS.cursor();
    _markupTableDS.object(fieldNum(MarkupTable, METFollowTransactionTaxItemGroup)).allowEdit(markupTable.METIsOffRemittance);
}
